<?php
namespace App\Modules\Inventory\Infrastructure\Persistence;
use App\Models\InventoryItem;use App\Models\InventoryMovement;use App\Models\ProductVariant;use App\Modules\Inventory\Application\DTOs\StockAdjustmentData;use App\Modules\Inventory\Domain\Contracts\InventoryRepositoryInterface;use App\Modules\Inventory\Domain\Exceptions\InsufficientStockException;use App\Modules\Inventory\Domain\Exceptions\InvalidStockAdjustmentException;use App\Modules\Inventory\Domain\Exceptions\InventoryNotFoundException;use Illuminate\Support\Facades\DB;
final class EloquentInventoryRepository implements InventoryRepositoryInterface{public function list():iterable{return InventoryItem::query()->with(['product','variant'])->latest()->get();}public function find(int $id):InventoryItem{$item=InventoryItem::query()->with(['product','variant'])->find($id);if(!$item)throw new InventoryNotFoundException('Inventory item not found.');return $item;}public function adjust(StockAdjustmentData $data,?int $actorId):InventoryItem{if($data->quantity===0)throw new InvalidStockAdjustmentException('Stock adjustment quantity cannot be zero.');return DB::transaction(function()use($data,$actorId){$item=$this->target($data->productId,$data->variantId);$next=$item->on_hand+$data->quantity;if($next<0||$next<$item->reserved)throw new InsufficientStockException('Stock cannot be lower than reserved quantity.');$item->update(['on_hand'=>$next]);InventoryMovement::query()->create(['inventory_item_id'=>$item->id,'actor_id'=>$actorId,'quantity'=>$data->quantity,'on_hand_after'=>$next,'reason'=>$data->reason,'note'=>$data->note]);return $item->fresh(['product','variant']);});}public function reserve(int $productId,?int $variantId,int $quantity):InventoryItem{if($quantity<=0)throw new InvalidStockAdjustmentException('Reservation quantity must be positive.');return DB::transaction(function()use($productId,$variantId,$quantity){$item=$this->target($productId,$variantId);if($item->available<$quantity)throw new InsufficientStockException('Insufficient available stock.');$item->increment('reserved',$quantity);return $item->fresh(['product','variant']);});}public function release(int $productId,?int $variantId,int $quantity):InventoryItem{if($quantity<=0)throw new InvalidStockAdjustmentException('Release quantity must be positive.');return DB::transaction(function()use($productId,$variantId,$quantity){$item=$this->target($productId,$variantId);if($item->reserved<$quantity)throw new InvalidStockAdjustmentException('Cannot release more stock than reserved.');$item->decrement('reserved',$quantity);return $item->fresh(['product','variant']);});}private function target(int $productId,?int $variantId):InventoryItem{$query=InventoryItem::query()->where('product_id',$productId);if($variantId===null){$query->whereNull('variant_id');}else{if(!ProductVariant::query()->whereKey($variantId)->where('product_id',$productId)->exists())throw new InventoryNotFoundException('Product variant does not belong to product.');$query->where('variant_id',$variantId);}$item=$query->first();return $item??InventoryItem::query()->create(['product_id'=>$productId,'variant_id'=>$variantId]);}}
